--
-- Table structure for table `schedule_batches`
--

CREATE TABLE `schedule_batches` (
  `batch_id` bigint UNSIGNED NOT NULL,
  `academic_period_id` int UNSIGNED NOT NULL,
  `program_id` int UNSIGNED NOT NULL,
  `data_origin` enum('DEMO','OFFICIAL') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('ACTIVE','SUPERSEDED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

