--
-- Table structure for table `special_classes`
--

CREATE TABLE `special_classes` (
  `special_class_id` bigint UNSIGNED NOT NULL,
  `academic_period_id` int UNSIGNED NOT NULL,
  `program_id` int UNSIGNED NOT NULL,
  `subject_id` int UNSIGNED NOT NULL,
  `class_type` enum('REMEDIAL','IRREGULAR','OCTOBERIAN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `recurrence` enum('WEEKLY') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WEEKLY',
  `teacher_id` int UNSIGNED DEFAULT NULL,
  `approved_duration_minutes` smallint UNSIGNED DEFAULT NULL,
  `approval_reference` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('DRAFT','ACTIVE','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `data_origin` enum('DEMO','OFFICIAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DEMO',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `special_class_meetings`
--

CREATE TABLE `special_class_meetings` (
  `special_meeting_id` bigint UNSIGNED NOT NULL,
  `special_class_id` bigint UNSIGNED NOT NULL,
  `meeting_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `room_id` int UNSIGNED DEFAULT NULL,
  `teacher_id` int UNSIGNED NOT NULL,
  `delivery_mode` enum('F2F','ONLINE') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('SCHEDULED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SCHEDULED',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `special_class_policies`
--

CREATE TABLE `special_class_policies` (
  `special_class_policy_id` bigint UNSIGNED NOT NULL,
  `academic_period_id` int UNSIGNED NOT NULL,
  `program_id` int UNSIGNED NOT NULL,
  `class_type` enum('REMEDIAL','IRREGULAR','OCTOBERIAN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `recurrence` enum('WEEKLY') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WEEKLY',
  `approved_duration_minutes` smallint UNSIGNED DEFAULT NULL,
  `delivery_mode` enum('F2F','ONLINE') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `policy_status` enum('PENDING','APPROVED','REVOKED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `approval_reference` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_by` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approval_evidence_sha256` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `octoberian_specific_rules_approved` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `special_class_students`
--

CREATE TABLE `special_class_students` (
  `special_class_id` bigint UNSIGNED NOT NULL,
  `student_number` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `students`
--

CREATE TABLE `students` (
  `student_id` bigint UNSIGNED NOT NULL,
  `student_number` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `first_name` varchar(80) COLLATE utf8mb4_general_ci NOT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `program_id` int UNSIGNED NOT NULL,
  `academic_period_id` int UNSIGNED NOT NULL,
