--
-- Table structure for table `subjects`
--

CREATE TABLE `subjects` (
  `subject_id` int UNSIGNED NOT NULL,
  `program_id` int UNSIGNED NOT NULL,
  `subject_code` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `specialization` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subject_title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `units` decimal(5,2) NOT NULL,
  `f2f_hours` decimal(5,2) NOT NULL,
  `online_hours` decimal(5,2) NOT NULL,
  `year_level` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `semester` tinyint UNSIGNED NOT NULL,
  `legacy_subject_id` int UNSIGNED DEFAULT NULL,
  `is_verified` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

